{
  "title": "Discussion on taxes, domain, and low‑profit app ideas",
  "topics": [
    {
      "id": "tax-filing",
      "title": "Complications with tax declarations",
      "claims": [
        {
          "text": "Author paid 500 UAH to aunt Sveta to correct a large tax‑declaration mistake and avoided larger fines by re‑filing correctly (about 1000 UAH paid).",
          "evidence": [1]
        },
        {
          "text": "The inspector had not reviewed the author’s declarations for 1.5 years, simply approved them, then was reprimanded and began demanding re‑checks of all years.",
          "evidence": [1]
        },
        {
          "text": "The main difficulty is not calculating tax amounts but ensuring each column is correctly matched and subtractions are applied.",
          "evidence": [8]
        },
        {
          "text": "The whole procedure can be done in about an hour with Excel, roughly one day per month.",
          "evidence": [5, 6, 7]
        }
      ]
    },
    {
      "id": "domain‑purchase",
      "title": "Whether to buy a domain",
      "claims": [
        {
          "text": "Participant P2 states they have not bought a domain.",
          "evidence": [2]
        },
        {
          "text": "P4 jokes that nobody would buy a domain.",
          "evidence": [9, 10]
        },
        {
          "text": "P1 sarcastically suggests that buying a calculator would free up money for a domain.",
          "evidence": [4]
        }
      ]
    },
    {
      "id": "app‑profitability",
      "title": "Profit potential of a lightweight web/app product",
      "claims": [
        {
          "text": "Web is the simplest platform but less profitable than Android/iOS; SEO is poor, no external traffic, and app stores promote new apps more effectively.",
          "evidence": [11]
        },
        {
          "text": "User retention is near zero because a paywall appears within the first 10 seconds, deterring purchases.",
          "evidence": [11]
        },
        {
          "text": "Conversion is assumed to be negligible; the product lacks bank or tax‑payer‑cabinet integrations.",
          "evidence": [11]
        },
        {
          "text": "A successful case mentioned requires fast delivery (< 1 week) and a cross‑platform stack (Flutter), copying popular features with minor tweaks.",
          "evidence": [12]
        },
        {
          "text": "P1 doubts anyone would buy this product after a few months.",
          "evidence": [17]
        }
      ]
    },
    {
      "id": "calculator‑limitations",
      "title": "Restrictions of the tax calculator",
      "claims": [
        {
          "text": "The calculator only works with hryvnia‑based FOP; the author had to convert all transactions using the daily exchange rate.",
          "evidence": [19]
        }
      ]
    },
    {
      "id": "security‑and‑pricing",
      "title": "Security concerns and price expectations for the app",
      "claims": [
        {
          "text": "P4 suggests the app is marketed as a local‑first tool with USD/UAH rates updated every 5 minutes, but the paid bundle actually contains the source code.",
          "evidence": [29]
        },
        {
          "text": "P4 implies the password is stored in local storage as a 100 % discount promo code.",
          "evidence": [20]
        },
        {
          "text": "P1 believes most LinkedIn users could hack the app easily.",
          "evidence": [28]
        },
        {
          "text": "P5 labels the approach as piracy and jokes about asking the developer for the password.",
          "evidence": [24, 25, 27]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": [
    {
      "text": "Is there a market of at least ten people willing to pay 299 UAH for the app?",
      "evidence": [20]
    }
  ]
}
